import { Mesh, PlaneGeometry, Group, Color, DoubleSide, AdditiveBlending } from 'three/webgpu';
import * as tsl from 'three/tsl';
import { gsap } from 'gsap';
import primitives from '@/primitives';
import { createMSDFText } from '@/text';

export default function createNode(config, ctx) {
  // Root group
  const root = new Group();
  root.position.set(
    config.position?.[0] ?? 0,
    config.position?.[1] ?? 0,
    config.position?.[2] ?? 0
  );
  root.rotation.set(
    config.rotation?.[0] ?? 0,
    config.rotation?.[1] ?? 0,
    config.rotation?.[2] ?? 0
  );
  root.scale.set(
    config.scale?.[0] ?? 1,
    config.scale?.[1] ?? 1,
    config.scale?.[2] ?? 1
  );

  // Load textures synchronously (cached)
  const mainTex = ctx.textureLoader.load(config.assets?.imageUrl);
  const depthTex = ctx.textureLoader.load(config.assets?.depthMapUrl);

  // Plane geometry – 4 × 2.5 scene units, 64 × 64 segments
  const PLANE_W = 4.0;
  const PLANE_H = 2.5;
  const geometry = new PlaneGeometry(PLANE_W, PLANE_H, 64, 64);

  // TSL nodes for material
  const texNode = tsl.texture(mainTex);
  const depthNode = tsl.texture(depthTex);
  const displacementScaleNode = tsl.float(0.18);

  // Simple filmic grade approximation
  const liftedBlacks = tsl.float(0.07); // lift blacks
  const contrastBoost = tsl.float(1.12);
  const desat = tsl.float(0.92);
  const redPreserve = tsl.float(1.0);
  const gradedColor = tsl
    .mix(
      tsl.luminance(texNode).multiplyScalar(desat),
      texNode,
      tsl.vec3(redPreserve, 1, 1)
    )
    .addScalar(liftedBlacks)
    .multiplyScalar(contrastBoost);

  // Opacity animated node
  const opacityNode = tsl.float(0.0);
  const material = tsl.standardMaterial({
    map: texNode,
    displacementMap: depthNode,
    displacementScale: displacementScaleNode,
    baseColor: gradedColor,
    opacity: opacityNode,
    transparent: true,
    side: DoubleSide,
  });

  const planeMesh = new Mesh(geometry, material);
  planeMesh.position.set(0, 0, 0);
  root.add(planeMesh);

  // Bottom scrim gradient (full width, small height)
  const SCRIM_H = 0.6; // enough to hold caption block
  const scrimGeom = new PlaneGeometry(PLANE_W, SCRIM_H);
  const gradNode = tsl
    .mix(
      tsl.vec4(0, 0, 0, 0),
      tsl.vec4(0, 0, 0, 0.933), // #0b0b10eb => 0.933 alpha
      tsl.smoothstep(tsl.float(0.45), tsl.float(1.0), tsl.y)
    );
  const scrimMat = tsl.standardMaterial({
    baseColor: gradNode,
    side: DoubleSide,
    transparent: true,
    opacity: tsl.float(1.0),
  });
  const scrimMesh = new Mesh(scrimGeom, scrimMat);
  scrimMesh.position.set(0, -PLANE_H / 2 + SCRIM_H / 2, 0.001);
  root.add(scrimMesh);

  // Text block parameters
  const padding = 0.5; // base unit * 2
  const baseline = 0.25;
  const startX = -PLANE_W / 2 + padding;
  let cursorY = -PLANE_H / 2 + padding;

  const textColor = new Color(config.visual?.colors?.ink ?? '#16161d');

  // Helper to create a line of MSDF text
  function addTextLine(content, style, lineIndex) {
    const txt = createMSDFText({
      text: content,
      fontFamily: style.family,
      fontSize: style.fontSize / 100, // convert px to scene units (approx)
      fontWeight: style.fontWeight,
      letterSpacing: style.letterSpacing,
      lineHeight: style.lineHeight,
      color: textColor,
      atlas: ctx.fontAtlas,
      atlasRegion: config.atlasRegion, // { atlas:0, sourceRect... }
    });
    txt.position.set(startX, cursorY + lineIndex * baseline, 0.002);
    root.add(txt);
    return txt;
  }

  // Kicker
  const kickerStyle = config.typography?.kicker ?? {
    family: 'JetBrains Mono',
    fontSize: 9,
    fontWeight: 700,
    letterSpacing: 0.12,
    lineHeight: 1.2,
  };
  addTextLine('NOVA ATELIER / GENEVA', kickerStyle, 0);

  // Headline
  const headlineStyle = config.typography?.headline ?? {
    family: 'Lora',
    fontSize: 34,
    fontWeight: 600,
    letterSpacing: -0.01,
    lineHeight: 1.1,
  };
  addTextLine('Time, Machined.', headlineStyle, 1);

  // Accent hairline bar between headline and body
  const barWidth = 0.75 * PLANE_W;
  const barHeight = 0.02;
  const barGeom = new PlaneGeometry(barWidth, barHeight);
  const barMat = tsl.standardMaterial({
    emissive: tsl.vec3(1.0, 0.0, 0.0).multiplyScalar(1.8),
    side: DoubleSide,
    transparent: true,
    opacity: tsl.float(1.0),
    blending: AdditiveBlending,
  });
  const barMesh = new Mesh(barGeom, barMat);
  barMesh.position.set(0, cursorY + 2 * baseline - baseline * 0.5, 0.002);
  root.add(barMesh);

  // Body
  const bodyStyle = config.typography?.body ?? {
    family: 'JetBrains Mono',
    fontSize: 13,
    fontWeight: 400,
    letterSpacing: 0,
    lineHeight: 1.5,
  };
  addTextLine('Every case begins as a single billet of 904L steel.', bodyStyle, 3);

  // Caption
  const captionStyle = config.typography?.caption ?? {
    family: 'JetBrains Mono',
    fontSize: 9,
    fontWeight: 400,
    letterSpacing: 0.12,
    lineHeight: 1.4,
  };
  addTextLine('CALIBRE NA-01 / 72 HOUR RESERVE', captionStyle, 4);

  // Animations
  const timelines = [];

  // Plate mount fade‑in
  const plateTL = gsap.timeline();
  plateTL.to(opacityNode, {
    value: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });
  timelines.push(plateTL);

  // Caption block rise‑in (offsetting whole text group)
  const captionGroup = new Group(); // container for text lines & bar
  // Move previously added text meshes into this group
  root.children
    .filter((c) => c !== planeMesh && c !== scrimMesh && c !== barMesh)
    .forEach((c) => {
      captionGroup.add(c);
    });
  // Also include bar
  captionGroup.add(barMesh);
  captionGroup.position.y = -0.4; // start offset
  root.add(captionGroup);

  const riseTL = gsap.timeline({ delay: 0.12 });
  riseTL.to(captionGroup.position, {
    y: 0,
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)',
  });
  timelines.push(riseTL);

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(planeMesh, prim.params ?? {});
      }
    }
  }

  // User data
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    // Dispose geometry/materials
    geometry.dispose();
    material.dispose();
    scrimGeom.dispose();
    scrimMat.dispose();
    barGeom.dispose();
    barMat.dispose();
    // Text meshes disposal (assuming they expose dispose)
    captionGroup.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose();
        obj.material?.dispose();
      }
    });
    // Kill GSAP timelines
    timelines.forEach((tl) => tl.kill());
  };

  return root;
}
